 "content": "def transform(grid):
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(r.count(v) for r in grid))
    # Repeated bands indicate the shorter bar's missing continuation; highlight
    # the background immediately following its endpoint through the grid edge.
    bands = [(r, [c for c,v in enumerate(row) if v != bg]) for r,row in enumerate(grid)]
    active = [(r, cs) for r,cs in bands if cs]
    if len(active) >= 2:
        longest = max(len(cs) for _,cs in active)
        for r, cs in active:
            if len(cs) < longest and cs[0] == 0:
                for c in range(cs[-1]+1, len(grid[r])):
                    out[r][c] = 1
    return out
